"""Bundles: high-level presets that configure iSpy for a particular application.

A bundle is a JSON file in the top-level ``Bundles/`` directory that enables a
set of plugins, applies config overrides, and selects a unit pack. Applying a
bundle writes to config.json (takes effect after restart).
"""

import json
import logging
from pathlib import Path

logger = logging.getLogger(__name__)

_REPO_ROOT = Path.cwd()
_BUNDLES_DIR = _REPO_ROOT / "Bundles"

_BUILTIN = {}


def _load_bundles() -> dict:
    bundles = dict(_BUILTIN)
    try:
        if _BUNDLES_DIR.exists():
            for path in sorted(_BUNDLES_DIR.glob("*.json")):
                try:
                    data = json.loads(path.read_text(encoding="utf-8"))
                    key = str(data.get("key") or path.stem)
                    data.setdefault("key", key)
                    bundles[key] = data
                except Exception as e:
                    logger.warning("Could not load bundle %s: %s", path, e)
    except Exception as e:
        logger.warning("Bundle discovery failed: %s", e)
    return bundles


_BUNDLES = _load_bundles()


def list_bundles() -> list[dict]:
    return list(_BUNDLES.values())


def get_bundle(key: str) -> dict | None:
    return _BUNDLES.get(str(key).lower().strip())


def reload_bundles() -> None:
    global _BUNDLES
    _BUNDLES = _load_bundles()


def apply_bundle(config, bundle: dict) -> None:
    """Apply a bundle to an iSpyConfig instance (in memory; caller saves)."""
    if not isinstance(bundle, dict):
        return
    unit = bundle.get("unit")
    if unit:
        try:
            config.set("unit", unit)
        except Exception:
            pass
    overrides = bundle.get("config") or {}
    if isinstance(overrides, dict):
        for k, v in overrides.items():
            try:
                config.set(k, v)
            except Exception:
                pass
    plugins = bundle.get("plugins")
    if isinstance(plugins, dict):
        try:
            existing = config.get("plugins")
            if not isinstance(existing, dict):
                existing = {}
            for ptype, entries in plugins.items():
                if not isinstance(entries, dict):
                    continue
                existing[ptype] = entries
            config.set("plugins", existing)
        except Exception:
            pass